1	/* Home motion probe for the tablet/desktop app — Phase 1 gate.
2	 *
3	 * Covers the two things Phase 1 added that no existing script asserts:
4	 *
5	 *   §5.1  one sliding indicator travels between range buttons, rather than each
6	 *         button painting its own background;
7	 *   §5.2  the bucket chart morphs between range sets instead of snapping.
8	 *
9	 * §5.2's acceptance is explicitly *not* "the final chart looks right", so this
10	 * probe samples mid-flight. Gating failures:
11	 *
12	 *   NO BAR MOTION      a range change ran no bar animation at all — the morph is
13	 *                      not wired, or a key change silently replaced it.
14	 *   FIRST-FRAME JUMP   one frame after the click the bars already sit at their
15	 *                      target width. That is the reflow snap the FLIP exists to
16	 *                      absorb.
17	 *   INDICATOR STUCK    the range indicator did not move between two ranges.
18	 *   STUCK EXIT NODE    a `.dt-morph-exit` layer outlived its generation. The
19	 *                      layer is inert and absolutely positioned, so a leaked one
20	 *                      is invisible in a screenshot but accumulates forever.
21	 *   COUNT MISMATCH     bars, labels and buttons disagree after settling.
22	 *   LABEL REGRESSION   a bar button lost its aria-label or aria-pressed.
23	 *
24	 * Usage: dev server on :5000, single instance.
25	 *   node scripts/desktop-shots/probe-home-motion.mjs
26	 */
27	
28	import { BASE_URL, newRetailPage, CHROMIUM_PATH } from "./retail-fixtures.mjs";
29	import { chromium } from "playwright";
30	
31	/* The three target sizes from §10. Without `hasTouch` the pointer is fine and
32	   you get the desktop path, so the tablet classes are not actually tablets. */
33	const DEVICE_CLASSES = [
34	  ["desktop", { viewport: { width: 1440, height: 900 } }],
35	  ["tablet", { viewport: { width: 1194, height: 834 }, hasTouch: true, isMobile: false }],
36	  ["tablet-1366", { viewport: { width: 1366, height: 1024 }, hasTouch: true, isMobile: false }],
37	];
38	
39	const SURFACES = [
40	  { label: "retail", route: "/dashboard", p: "rh" },
41	  { label: "property", route: "/property", p: "ph" },
42	  { label: "trades", route: "/trades", p: "th" },
43	];
44	
45	const RANGES = ["day", "week", "month", "year"];
46	
47	/* The morph runs --m-dur-enter (280ms) with a 180ms fade; settle well past both. */
48	const SETTLE_MS = 700;
49	
50	/* `newRetailPage` already scopes HTTP-status errors to our own origin, but its
51	   `requestfailed` listener records every failed request including third-party
52	   ones — the Replit dev-banner tag in client/index.html (blocked by ORB) and the
53	   analytics beacon aborted on navigation. Neither can indicate a motion defect,
54	   and neither is ours to fix from this probe.
55	 *
56	 * So: a request failure to another origin is reported and not gated. Page
57	 * errors, console errors, our-origin HTTP errors and our-origin request
58	 * failures all still gate. */
59	const OUR_ORIGIN = new URL(BASE_URL).origin;
60	
61	function isExternalRequestFailure(entry) {
62	  const match = /request failed: \S+ (\S+)/.exec(String(entry));
63	  if (!match) return false;
64	  try {
65	    return new URL(match[1]).origin !== OUR_ORIGIN;
66	  } catch {
67	    return false;
68	  }
69	}
70	
71	/* Serialised into the page: no closures, everything arrives as arguments. */
72	const READ_STATE = (prefix) => {
73	  const scaleEl = document.querySelector("[data-desktop-scale]");
74	  const scale = scaleEl ? parseFloat(scaleEl.dataset.desktopScale) || 1 : 1;
75	
76	  const bars = [...document.querySelectorAll(`.${prefix}-bar`)];
77	  const buttons = [...document.querySelectorAll(`.${prefix}-bar-btn`)];
78	  const labels = [...document.querySelectorAll(`.${prefix}-bar-label`)];
79	  const indicator = document.querySelector(`.${prefix}-segs .dt-seg-indicator`);
80	
81	  const rect = (el) => {
82	    const r = el.getBoundingClientRect();
83	    return { x: r.left / scale, w: r.width / scale, h: r.height / scale };
84	  };
85	
86	  const barTargets = new Set(bars);
87	  const running = document.getAnimations().filter((a) => a.playState === "running");
88	
89	  return {
90	    barCount: bars.length,
91	    buttonCount: buttons.length,
92	    labelCount: labels.length,
93	    barWidths: bars.map((b) => Math.round(rect(b).w * 100) / 100),
94	    barHeights: bars.map((b) => Math.round(rect(b).h * 100) / 100),
95	    indicatorX: indicator ? Math.round(rect(indicator).x * 100) / 100 : null,
96	    indicatorW: indicator ? Math.round(rect(indicator).w * 100) / 100 : null,
97	    runningOnBars: running.filter((a) => barTargets.has(a.effect?.target)).length,
98	    runningTotal: running.length,
99	    exitLayers: document.querySelectorAll(".dt-morph-exit").length,
100	    /* An exit layer must never be reachable while it exists. */
101	    exitReachable: [...document.querySelectorAll(".dt-morph-exit")].filter(
102	      (el) => !el.inert || el.getAttribute("aria-hidden") !== "true",
103	    ).length,
104	    ariaMissing: buttons.filter(
105	      (b) => !b.getAttribute("aria-label") || b.getAttribute("aria-pressed") === null,
106	    ).length,
107	    pressedCount: buttons.filter((b) => b.getAttribute("aria-pressed") === "true").length,
108	  };
109	};
110	
111	async function probeSurface(page, surface, label, failures, notes) {
112	  const { p, route } = surface;
113	  const id = `${label}/${surface.label}`;
114	
115	  await page.goto(`${BASE_URL}${route}`, { waitUntil: "networkidle" });
116	  await page.waitForSelector(`.${p}-bar-btn`, { timeout: 15_000 });
117	  await page.waitForTimeout(SETTLE_MS);
118	
119	  let previous = await page.evaluate(READ_STATE, p);
120	  if (previous.barCount === 0) {
121	    failures.push(`${id}: NO BARS RENDERED`);
122	    return;
123	  }
124	
125	  for (const range of RANGES) {
126	    const button = page.locator(`.${p}-segs [data-seg-id="${range}"]`);
127	    if ((await button.count()) === 0) {
128	      failures.push(`${id}: missing range button "${range}"`);
129	      continue;
130	    }
131	
132	    const before = await page.evaluate(READ_STATE, p);
133	    await button.click();
134	
135	    /* One frame after the click: the FLIP must still be showing the outgoing
136	       geometry, not the freshly reflowed target. */
137	    const firstFrame = await page.evaluate(
138	      (prefix) =>
139	        new Promise((resolve) =>
140	          requestAnimationFrame(() => resolve(READ_STATE_INLINE(prefix))),
141	        ),
142	      p,
143	    );
144	
145	    const settled = await (async () => {
146	      await page.waitForTimeout(SETTLE_MS);
147	      return page.evaluate(READ_STATE, p);
148	    })();
149	
150	    const countChanged = before.barCount !== settled.barCount;
151	
152	    if (countChanged) {
153	      if (firstFrame.runningOnBars === 0) {
154	        failures.push(
155	          `${id}: NO BAR MOTION on → ${range} (${before.barCount}→${settled.barCount} bars)`,
156	        );
157	      }
158	      /* The defect is the bar *already sitting on* its target one frame in —
159	         the reflow snap the FLIP exists to absorb. It is not "closer to the
160	         target than to the source": --m-ease-out is an expo-out, which covers
161	         over half its distance in the first ~12% of the duration, so a healthy
162	         FLIP legitimately reads past the midpoint by the frame we can sample. */
163	      const oldW = before.barWidths[0];
164	      const newW = settled.barWidths[0];
165	      const firstW = firstFrame.barWidths[0];
166	      if (
167	        typeof oldW === "number" &&
168	        typeof newW === "number" &&
169	        typeof firstW === "number" &&
170	        Math.abs(newW - oldW) > 1 &&
171	        Math.abs(firstW - newW) < 1
172	      ) {
173	        failures.push(
174	          `${id}: FIRST-FRAME JUMP on → ${range} (was ${oldW}px, frame1 ${firstW}px already at target ${newW}px)`,
175	        );
176	      }
177	    }
178	
179	    if (before.indicatorX !== null && settled.indicatorX !== null) {
180	      if (before.indicatorX === settled.indicatorX && range !== RANGES[0]) {
181	        // Only a real failure when the previous range differed from this one.
182	        if (before.pressedCount >= 0 && countChanged) {
183	          failures.push(`${id}: INDICATOR STUCK at x=${settled.indicatorX} on → ${range}`);
184	        }
185	      }
186	    } else if (settled.indicatorX === null) {
187	      failures.push(`${id}: no range indicator found`);
188	    }
189	
190	    if (settled.exitLayers > 0) {
191	      failures.push(`${id}: STUCK EXIT NODE after → ${range} (${settled.exitLayers})`);
192	    }
193	    if (settled.exitReachable > 0) {
194	      failures.push(`${id}: EXIT LAYER REACHABLE after → ${range}`);
195	    }
196	    if (
197	      settled.barCount !== settled.buttonCount ||
198	      settled.barCount !== settled.labelCount
199	    ) {
200	      failures.push(
201	        `${id}: COUNT MISMATCH after → ${range} (bars ${settled.barCount}, buttons ${settled.buttonCount}, labels ${settled.labelCount})`,
202	      );
203	    }
204	    if (settled.ariaMissing > 0) {
205	      failures.push(
206	        `${id}: LABEL REGRESSION after → ${range} (${settled.ariaMissing} button(s) missing aria)`,
207	      );
208	    }
209	
210	    notes.push(
211	      `  ${id} → ${String(range).padEnd(6)} ${String(before.barCount).padStart(2)}→${String(settled.barCount).padStart(2)} bars   frame1 anim ${String(firstFrame.runningOnBars).padStart(2)}   x ${settled.indicatorX}`,
212	    );
213	    previous = settled;
214	  }
215	
216	  /* ── rapid interruption: two range changes inside one transition ── */
217	  await page.locator(`.${p}-segs [data-seg-id="year"]`).click();
218	  await page.waitForTimeout(40);
219	  await page.locator(`.${p}-segs [data-seg-id="day"]`).click();
220	  await page.waitForTimeout(SETTLE_MS * 2);
221	  const afterRapid = await page.evaluate(READ_STATE, p);
222	
223	  if (afterRapid.exitLayers > 0) {
224	    failures.push(`${id}: STUCK EXIT NODE after rapid switch (${afterRapid.exitLayers})`);
225	  }
226	  if (afterRapid.runningOnBars > 0) {
227	    failures.push(`${id}: ANIMATION STILL RUNNING after rapid switch`);
228	  }
229	  if (
230	    afterRapid.barCount !== afterRapid.buttonCount ||
231	    afterRapid.barCount !== afterRapid.labelCount
232	  ) {
233	    failures.push(`${id}: COUNT MISMATCH after rapid switch`);
234	  }
235	  notes.push(
236	    `  ${id} rapid year→day settles at ${afterRapid.barCount} bars, ${afterRapid.exitLayers} exit layers`,
237	  );
238	}
239	
240	async function run(browser, label, contextOptions) {
241	  const { context, page, errors } = await newRetailPage(browser, label, contextOptions);
242	  const failures = [];
243	  const notes = [];
244	
245	  /* READ_STATE is used both directly and inside a rAF promise; expose it once. */
246	  await page.addInitScript(
247	    `window.READ_STATE_INLINE = ${READ_STATE.toString()};`,
248	  );
249	
250	  for (const surface of SURFACES) {
251	    await probeSurface(page, surface, label, failures, notes);
252	  }
253	
254	  await context.close();
255	
256	  const realErrors = errors.filter((e) => !isExternalRequestFailure(e));
257	  return { failures, notes, realErrors, benign: errors.length - realErrors.length };
258	}
259	
260	const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
261	let failed = 0;
262	
263	for (const [label, contextOptions] of DEVICE_CLASSES) {
264	  console.log(`\n########## ${label} ##########`);
265	  const { failures, notes, realErrors, benign } = await run(browser, label, contextOptions);
266	  notes.forEach((n) => console.log(n));
267	
268	  if (failures.length === 0) {
269	    console.log(`  → ${label}: all range changes morph, indicator travels, no stuck nodes`);
270	  } else {
271	    failures.forEach((f) => console.log(`  ✗ ${f}`));
272	    failed += failures.length;
273	  }
274	  if (realErrors.length) {
275	    console.log(`  ✗ ${label} page errors (${realErrors.length}): ${realErrors[0]}`);
276	    failed += realErrors.length;
277	  }
278	  if (benign) {
279	    console.log(`  · ${label}: ${benign} third-party request failure(s) (analytics / dev banner), not gated`);
280	  }
281	}
282	
283	await browser.close();
284	
285	console.log(`\n===== summary =====`);
286	if (failed) {
287	  console.log(`FAIL — ${failed} home-motion defect(s)`);
288	  process.exit(1);
289	}
290	console.log("PASS — home motion gates clean on every device class");
