/* ── Terminal layout contract ─────────────────────────────────────────────
   One 340px content spine, shared by all three verticals' terminals. Neutral
   `.terminal-*` names on purpose: Retail proves the layout, then Property and
   Trades reuse the same utilities rather than a Retail-only class.

   Canvas frame of reference. The positioned terminal body starts at canvas
   x0/y67 (66px header + 1px divider). Its 26px top padding puts the right panel
   at canvas x632/y93, and the panel is 502px wide. The variables below are
   relative to that panel origin; the rail is positioned against the body.

     --terminal-spine-left    81px  → canvas x713
     --terminal-figure-top    62px  → canvas y155
     --terminal-content-top  175px  → canvas y268
     --terminal-cta-left     151px  → canvas x783
     --terminal-cta-top      655px  → canvas y748

   Zone B and the CTA share the centre at canvas x883, which is what makes the
   column read as one spine rather than three stacked blocks. */
.tapt-desktop-viewport .terminal-panel {
  --terminal-spine-left: 81px;
  --terminal-spine-width: 340px;
  --terminal-figure-top: 62px;
  --terminal-content-top: 175px;
  --terminal-content-max-h: 460px;
  --terminal-cta-left: 151px;
  --terminal-cta-top: 655px;
  --terminal-cta-width: 200px;
  --terminal-cta-height: 46px;

  position: relative;
  flex: 1;
  min-width: 0;
  box-sizing: border-box;
}

/* Zone A — the amount figure. */
.tapt-desktop-viewport .terminal-zone-a {
  position: absolute;
  left: var(--terminal-spine-left);
  top: var(--terminal-figure-top);
  width: var(--terminal-spine-width);
}

/* Zone B — the content spine. It owns its own overflow: long item names, large
   NZD values and the biggest live stock set must scroll inside 460px rather
   than push into Zone C. */
.tapt-desktop-viewport .terminal-zone-b {
  position: absolute;
  left: var(--terminal-spine-left);
  top: var(--terminal-content-top);
  width: var(--terminal-spine-width);
  max-height: var(--terminal-content-max-h);
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.tapt-desktop-viewport .terminal-zone-b::-webkit-scrollbar {
  display: none;
}

/* Zone C — the primary action, pinned so it cannot be pushed off the canvas. */
.tapt-desktop-viewport .terminal-zone-c {
  position: absolute;
  left: var(--terminal-cta-left);
  top: var(--terminal-cta-top);
  width: var(--terminal-cta-width);
  height: var(--terminal-cta-height);
  box-sizing: border-box;
}

/* The rail is positioned explicitly against the terminal body rather than
   derived from a slot margin or an absolutely-positioned child's static
   position — those produced a 461px box from a content sum that should be 460.
   `space-between` with gap:0 and flex:none children holds the exact box. */
.tapt-desktop-viewport .terminal-rail {
  position: absolute;
  left: 550px;
  top: 201px;
  width: 80px;
  height: 460px;
  box-sizing: border-box;
  padding-block: 30px;
  gap: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
}
.tapt-desktop-viewport .terminal-rail > * {
  flex: none;
}

/* ── Bucket morph exit layer ──────────────────────────────────────────────
   Visual residue of the outgoing bucket set, built by useBucketMorph out of
   synthesized spans rather than clones of the real bar buttons. It must never
   be reachable: `inert` is set on the node, and these rules keep it out of hit
   testing and above nothing that matters. */
.tapt-desktop-viewport .dt-morph-exit {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

/* ── Desktop list entrance ────────────────────────────────────────────────
   Named tablet/desktop lists (transaction history, live stock tiles, the
   Property/Trades directories, and in Phase 2 the active stack) enter with a
   short rise instead of the opacity-only row tier. This is a deliberate,
   limited override of that one tier in docs/PLAN-2026-08-15-motion-toning.md;
   page, panel, modal, navigation and phone motion are untouched.

